//! Same retained profile-None checkpoint, one ordinary tick in each frozen library.
use lh_sim::runtime::Runtime;
use serde_json::{Value,json};
fn main(){let a:Vec<_>=std::env::args().collect();assert_eq!(a.len(),3);let out=std::path::Path::new(&a[2]);std::fs::create_dir(out).unwrap();let bytes=std::fs::read(&a[1]).unwrap();let mut r=Runtime::from_getup_checkpoint(&bytes).unwrap();let v:Value=serde_json::from_str(&r.verify_getup_checkpoint(&bytes).unwrap()).unwrap();assert_eq!(v["physicsIntegrations"],0);let before:Value=serde_json::from_str(&r.getup_fixture_report().unwrap()).unwrap();assert!(before["profile"].get("root_rotation_normalization").is_none());let reply=r.advance(1).unwrap();assert_eq!(reply.completed_ticks,1);assert!(reply.failure.is_none());let after:Value=serde_json::from_str(&r.getup_fixture_report().unwrap()).unwrap();let n=after["nativeSubsteps"].as_u64().unwrap()-before["nativeSubsteps"].as_u64().unwrap();assert_eq!(n,20);std::fs::write(out.join("reply.json"),serde_json::to_vec_pretty(&reply).unwrap()).unwrap();std::fs::write(out.join("checkpoint-after.bin"),r.getup_checkpoint().unwrap()).unwrap();std::fs::write(out.join("report-after.json"),r.getup_report().unwrap()).unwrap();std::fs::write(out.join("fixture-after.json"),r.getup_fixture_report().unwrap()).unwrap();let result=json!({"physicsIntegrations":n,"forecastIntegrations":0,"inputVerification":v,"beforeNative":before["nativeSubsteps"],"afterNative":after["nativeSubsteps"],"rootPolicyFieldOmitted":true});std::fs::write(out.join("result.json"),serde_json::to_vec_pretty(&result).unwrap()).unwrap();println!("{result}");}
